S = "Hakeem Force Academy"
QS = [
(S, "Who issues an ordinance in Pakistan?", ["The Prime Minister", "The President", "The Chief Justice", "The Speaker of the National Assembly"], 1,
 "Under Article 89 of the 1973 Constitution, the President can promulgate an ordinance when the National Assembly is not in session. It has the same force as an Act of Parliament for a limited time.",
 "An ordinance issued by the President lapses after 120 days unless Parliament extends or passes it.", [5070, 5207]),
(S, "Which of the following is a principal organ of the United Nations?", ["World Health Organization", "International Court of Justice", "UNICEF", "International Monetary Fund"], 1,
 "The six principal organs of the UN are the General Assembly, Security Council, Economic and Social Council, Trusteeship Council, International Court of Justice and the Secretariat. The others listed are agencies or funds.",
 "The International Court of Justice sits at The Hague and is the only principal organ not based in New York.", [1318]),
(S, "What are the coordinates of the origin on a Cartesian graph?", ["(1, 1)", "(0, 1)", "(0, 0)", "(1, 0)"], 2,
 "The origin is the point where the x-axis and y-axis cross, so both its x and y values are zero.",
 "The two axes divide the plane into four quadrants that meet at the origin.", [3158]),
(S, "Who built the Quba Mosque, the first mosque in Islam?", ["Hazrat Umar (RA)", "Prophet Muhammad (PBUH)", "Hazrat Abu Bakr (RA)", "Hazrat Uthman (RA)"], 1,
 "The Prophet (PBUH) laid the foundation of the Quba Mosque near Madinah on his Hijrah, and the Companions helped build it.",
 "The Quran (Surah At-Tawbah) refers to a mosque founded on piety from the first day, which scholars identify as Quba.", [5239]),
(S, "Who originally built the Kaaba?", ["Hazrat Ibrahim (AS)", "Hazrat Musa (AS)", "Hazrat Nuh (AS)", "Hazrat Isa (AS)"], 0,
 "Hazrat Ibrahim (AS), with the help of his son Hazrat Ismail (AS), raised the walls of the Kaaba by Allah's command. This is the answer given in most Pakistani textbooks.",
 "Some traditions say the Kaaba was first built by Hazrat Adam (AS) or the angels, so sources differ.", [5043, 687]),
(S, "What is another name of the Battle of Ahzab?", ["Battle of Badr", "Battle of the Trench (Khandaq)", "Battle of Hunain", "Battle of Khyber"], 1,
 "The Battle of Ahzab (the Confederates) in 5 AH is also called the Battle of Khandaq because the Muslims dug a trench around Madinah on the advice of Hazrat Salman Farsi (RA).",
 "The Quraysh and their allied tribes besieged Madinah for about a month and then withdrew.", [3875]),
(S, "Out of 15000 students, 12000 are present. What is the percentage of students present?", ["75%", "85%", "80%", "90%"], 2,
 "Percentage = 12000 / 15000 x 100 = 0.8 x 100 = 80%.",
 "The percentage absent is 100 - 80 = 20%, which is 3000 students.", [1005]),
(S, "In which period was the first war between Pakistan and India over Kashmir fought?", ["1947-48", "1965", "1971", "1999"], 0,
 "The first Indo-Pak war over Kashmir began in October 1947 after tribal and Pakistani forces entered the state and India sent troops. It ended with a UN-brokered ceasefire on 1 January 1949.",
 "The ceasefire line later became the Line of Control after the Simla Agreement of 1972.", [4285]),
(S, "Mark Zuckerberg is the founder and head of which company?", ["Meta Platforms (formerly Facebook)", "Microsoft", "Google", "Amazon"], 0,
 "Mark Zuckerberg co-founded Facebook in 2004 and is the chairman and CEO of its parent company, Meta Platforms.",
 "Facebook Inc. renamed itself Meta Platforms in October 2021; the company also owns Instagram and WhatsApp.", [991]),
(S, "The Dawn newspaper is owned by which family-run group?", ["The Haroon family (Dawn Media Group)", "The Sharif family", "The Shaheen family", "The Mir Shakil-ur-Rahman family"], 0,
 "Dawn is published by Dawn Media Group, which is controlled by the Haroon family (with the Saigol family). The Haroon family bought majority shares in 1946.",
 "Dawn was founded by Quaid-e-Azam Muhammad Ali Jinnah in Delhi in 1941.", [5169]),
(S, "After which war was the Simla Agreement signed between Pakistan and India?", ["1948 war", "1965 war", "1971 war", "Kargil conflict"], 2,
 "The Simla Agreement of July 1972 was signed after the 1971 war and the separation of East Pakistan.",
 "It was signed by Zulfikar Ali Bhutto and Indira Gandhi.", [755]),
(S, "Who signed the Simla Agreement of 1972 on behalf of India?", ["Lal Bahadur Shastri", "Jawaharlal Nehru", "Morarji Desai", "Indira Gandhi"], 3,
 "The Indian Prime Minister at that time, Indira Gandhi, signed the Simla Agreement on 2 July 1972.",
 "Zulfikar Ali Bhutto signed for Pakistan.", [5282]),
(S, "Between which two countries was the Tashkent Declaration of 1966 signed?", ["Pakistan and Afghanistan", "India and China", "Pakistan and India", "Pakistan and China"], 2,
 "The Tashkent Declaration of January 1966 ended the 1965 war between Pakistan and India, with the Soviet Union mediating.",
 "Indian Prime Minister Lal Bahadur Shastri died in Tashkent soon after signing it.", [1829]),
(S, "What was the Gandhi-Irwin Pact of 1931?", ["An agreement that ended the Civil Disobedience Movement and let Gandhi attend the Second Round Table Conference", "A partition plan for Bengal", "An agreement to form Pakistan", "A pact between Congress and the Muslim League"], 0,
 "The Gandhi-Irwin Pact was signed on 5 March 1931 between Mahatma Gandhi and the Viceroy Lord Irwin. Congress suspended civil disobedience and the government released political prisoners.",
 "Gandhi then attended the Second Round Table Conference in London in 1931.", [4135]),
(S, "Which type of medicine is used to reduce pain?", ["Vaccine", "Antibiotic", "Analgesic", "Antiseptic"], 2,
 "Analgesics (painkillers) such as paracetamol and aspirin relieve pain. Vaccines prevent disease and antibiotics kill bacteria.",
 "Anaesthetics are different from analgesics because they cause loss of sensation.", [1024, 4940]),
(S, "On which date was the Pakistan-China border agreement signed?", ["2 March 1963", "21 May 1951", "5 February 1972", "14 August 1949"], 0,
 "Pakistan and China signed the border agreement in Beijing on 2 March 1963, fixing the boundary between Gilgit-Baltistan and Xinjiang.",
 "Pakistan and China established diplomatic relations on 21 May 1951.", [146]),
(S, "By what name is the boundary line between Pakistan and India known?", ["Durand Line", "McMahon Line", "Radcliffe Line", "Line of Control"], 2,
 "The international border between Pakistan and India was drawn in 1947 by the Radcliffe Boundary Commission, headed by Sir Cyril Radcliffe.",
 "The Durand Line is the Pakistan-Afghanistan border.", [3829]),
(S, "In which year was the North-West Frontier Province renamed Khyber Pakhtunkhwa?", ["2001", "2008", "2010", "2013"], 2,
 "The 18th Constitutional Amendment, passed in April 2010, renamed the NWFP as Khyber Pakhtunkhwa.",
 "The province was earlier called NWFP from 1901 under British rule.", [1245]),
(S, "Which area of Pakistan is called the Switzerland of Pakistan?", ["Faisalabad", "Swat", "Multan", "Karachi"], 1,
 "Swat valley is known as the Switzerland of Pakistan for its mountains, rivers and green scenery.",
 "Faisalabad, by contrast, is known as the Manchester of Pakistan.", [3958]),
(S, "In which city is Ayub National Park located?", ["Lahore", "Rawalpindi", "Peshawar", "Islamabad"], 1,
 "Ayub National Park is a large public park on Murree Road in Rawalpindi, named after President Ayub Khan.",
 "It has a lake, a zoo-like area and recreation facilities for families.", [2538, 434]),
(S, "Under the 1973 Constitution of Pakistan, which institution is supreme?", ["The President", "The Parliament", "The Army", "The Governor"], 1,
 "The 1973 Constitution set up a parliamentary system in which the Parliament is the supreme law-making body and the Prime Minister heads the government.",
 "In practice the Constitution itself is supreme, and Parliament must act within it.", [1931]),
(S, "What is the parliament of Israel called?", ["Duma", "Knesset", "Majlis", "Bundestag"], 1,
 "The Israeli parliament is called the Knesset and it has 120 members.",
 "The Knesset sits in Jerusalem.", [3657]),
(S, "In which year was Bengal partitioned by the British?", ["1857", "1911", "1905", "1947"], 2,
 "Lord Curzon partitioned Bengal in 1905 into East Bengal and Assam and the rest of Bengal.",
 "The partition was annulled in 1911.", [959, 375, 297]),
(S, "On which date did the partition of Bengal take effect?", ["16 October 1905", "20 July 1905", "30 December 1906", "23 March 1940"], 0,
 "The partition of Bengal came into effect on 16 October 1905.",
 "Muslims celebrated it, while Hindus observed the day as a day of mourning.", [1116, 263]),
(S, "Whom did the partition of Bengal of 1905 benefit most?", ["Hindu landlords", "Muslims of East Bengal", "Congress leaders", "Sikhs of Punjab"], 1,
 "The new province of East Bengal and Assam had a Muslim majority, and Muslims got better chances in education, jobs and trade.",
 "Hindu leaders opposed the partition and launched the Swadeshi movement.", [2940, 704]),
(S, "Which Viceroy partitioned Bengal in 1905?", ["Lord Mountbatten", "Lord Curzon", "Lord Ripon", "Lord Minto"], 1,
 "Lord Curzon was the Viceroy of India from 1899 to 1905 and he carried out the partition of Bengal.",
 "The Muslim League was founded in 1906, soon after the partition.", [4714]),
(S, "Geographically, into how many main regions is Pakistan divided according to most textbooks?", ["3", "4", "6", "8"], 2,
 "Pakistan is usually divided into six regions: Northern Highlands, Western Highlands, Balochistan Plateau, Potohar Plateau and Salt Range, Indus Plain, and Deserts.",
 "Some books group them into three or five regions, so sources differ.", [2053, 985, 2775]),
(S, "Who is the chairman of the Pakistan Peoples Party (PPP)?", ["Asif Ali Zardari", "Bilawal Bhutto Zardari", "Yousaf Raza Gilani", "Murad Ali Shah"], 1,
 "Bilawal Bhutto Zardari has been PPP chairman since 2007 and was re-elected in April 2025.",
 "Asif Ali Zardari is the co-chairperson of the party.", [5119]),
(S, "On what date was the Indian Independence Act passed by the British Parliament?", ["3 June 1947", "18 July 1947", "14 August 1947", "15 August 1947"], 1,
 "The Indian Independence Act received royal assent on 18 July 1947 and created the two dominions of Pakistan and India.",
 "The 3 June 1947 plan was announced by Lord Mountbatten before the Act.", [1570]),
(S, "If 5 men write 5 pages in 5 minutes, how many pages will one man write in 5 minutes?", ["1", "5", "25", "0.2"], 0,
 "5 men write 5 pages in 5 minutes, so each man writes 1 page in 5 minutes.",
 "The rate is 1 page per man per 5 minutes, or 0.2 pages per minute.", [1982, 866]),
(S, "In a bus of 30 passengers, 2/3 are men and the rest are girls. What is the percentage of girls?", ["25%", "33.33%", "40%", "66.67%"], 1,
 "Men = 2/3 x 30 = 20, so girls = 30 - 20 = 10. Percentage of girls = 10/30 x 100 = 33.33%.",
 "Girls are 1/3 of the passengers.", [2487]),
]
